async function registryCall(action,data={}){const r=await fetch('/api/integrations/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function registryLoad(){const d=await registryCall('list');document.getElementById('registry-records').innerHTML=d.records.map(r=>`<form class="card prose registry-edit"><h2>${esc(r.id)}</h2><input type="hidden" name="id" value="${esc(r.id)}"><input type="hidden" name="version" value="${r.version}"><label>Owner<input name="owner" value="${esc(r.owner)}" maxlength="120" required ${d.role==='student'?'disabled':''}></label><label>Purpose<input name="purpose" value="${esc(r.purpose)}" maxlength="500" required ${d.role==='student'?'disabled':''}></label><label>Status<select name="status" ${d.role==='student'?'disabled':''}>${['Planned','Configured but disabled','Unavailable'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label><p>${esc(r.health)} · Authentication: ${esc(r.authentication)} · Permissions: ${esc(r.permissions)}</p><p>Data exchanged: None · Sync: Disabled · Last successful sync: Never</p><p>Consent: Required before enabling · Retention: Not configured</p>${d.role==='instructor'?'<button class="button">Save planning record</button>':''}</form>`).join('');document.getElementById('registry-status').textContent='Loaded from the tenant database. No external connections are active.';}
const beforeRegistry=render;render=function(){if(location.hash!=='#integration-center')return beforeRegistry();document.getElementById('app').innerHTML=integratedShell('integration-center',heading('Integration Center','Scholarion Academy · External services are not connected')+`<section class="card prose"><a href="#enterprise-controls">Enterprise controls</a> · <a href="#calendar">Calendar</a><p>Pilot instructors can maintain planning records. Connection states require verified service evidence and cannot be enabled here.</p><p id="registry-status" role="status">Connect to view integration records.</p></section><div id="registry-records"></div>`,model.role);bind();if(governedToken)registryLoad().catch(e=>document.getElementById('registry-status').textContent=e.message);};
document.addEventListener('submit',async e=>{if(e.target.id!=='registry-connect'&&!e.target.matches('.registry-edit'))return;e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(e.target.id==='registry-connect'){governedToken=d.token;e.target.reset();}else{d.version=Number(d.version);await registryCall('update',d);}await registryLoad();}catch(err){document.getElementById('registry-status').textContent=err.message;}});
const registryRender=render;render=function(){registryRender();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#integration-center"]'))nav.insertAdjacentHTML('beforeend','<a href="#integration-center">Integration Center</a>');};
render();
